  return(sin(5*pi*x));
}

path foo = (-0.1,sinefunction(-0.1));

for (x = -0.1; x <= 4; x = x + 0.01) {
  foo = foo--(x,sinefunction(x));
}

draw(graph(logfunction,0.05,4),red);
draw(foo,blue);
draw((-0.1,0)--(4,0));
draw((0,-1)--(0,1));

