for (int i=1; i<=4; ++i)
{
	draw((i,-.15)--(i,.15));
    if (i < 4)
    	draw((-.15,i)--(.15,i));
}
pair A=(0,0), B=(1,2), C=(3,3), D=(4,0);
draw(A--B--C--D--A);
dot("$A$",A,SW);
dot("$B$",B,NW);
dot("$C$",C,N);
dot("$D$",D,S);
pair E=(27/8,15/8);
